23	function resolveElements(root: HTMLElement): MarqueeElements | null {
24	  const viewport = root.querySelector<HTMLElement>(MARQUEE.viewportSelector);
25	  const track = root.querySelector<HTMLElement>(MARQUEE.trackSelector);
26	  const item = root.querySelector<HTMLElement>(MARQUEE.itemSelector);
27	  if (!viewport || !track || !item) return null;
28	  return { root, viewport, track, item };
29	}
