31	class MarqueeItemRuntime {
32	  private readonly _elements: MarqueeElements;
33	  private readonly _speed: number;
34	  private readonly _pauseOnHover: boolean;
35	  private _groupWidth = 0;
36	  private _tween: { kill?: () => void; pause?: () => void; resume?: () => void } | null = null;
37	  private _clones: HTMLElement[] = [];
38	  private _resizeObserver: ResizeObserver | null = null;
39	  private _handleResize = (): void => this.refresh();
40	  private _handleMouseEnter = (): void => {
41	    if (!this._pauseOnHover) return;
42	    this._tween?.pause?.();
43	  };
44	  private _handleMouseLeave = (): void => {
45	    if (!this._pauseOnHover) return;
46	    this._tween?.resume?.();
47	  };
48	
49	  constructor(item: MarqueeItem) {
50	    this._elements = item.elements;
51	    this._speed = item.speed;
52	    this._pauseOnHover = item.pauseOnHover;
53	  }
54	
55	  init(): void {
56	    this.dispose();
57	    this._buildClones();
58	    this.refresh();
59	    window.addEventListener("resize", this._handleResize);
60	    this._elements.root.addEventListener("mouseenter", this._handleMouseEnter);
61	    this._elements.root.addEventListener("mouseleave", this._handleMouseLeave);
62	    this._observeResize();
63	  }
64	
65	  refresh(): void {
66	    this._killTween();
67	    this._elements.track.style.transform = "translate3d(0, 0, 0)";
68	    this._buildClones();
69	    this._groupWidth = this._elements.item.offsetWidth;
70	    if (this._groupWidth <= 0) return;
71	
72	    const duration = this._groupWidth / this._speed;
73	    const gsap = getGsap();
74	    if (!gsap) {
75	      this._elements.root.style.setProperty(
76	        MARQUEE.fallbackDurationVar,
77	        `${duration}s`,
78	      );
79	      this._elements.root.classList.add(MARQUEE.fallbackClass);
80	      return;
81	    }
82	
83	    this._elements.root.classList.remove(MARQUEE.fallbackClass);
84	    this._tween = gsap.to(this._elements.track, {
85	      x: -this._groupWidth,
86	      duration,
87	      ease: "none",
88	      repeat: -1,
89	    }) as { kill?: () => void; pause?: () => void; resume?: () => void };
90	  }
91	
92	  dispose(): void {
93	    window.removeEventListener("resize", this._handleResize);
94	    this._elements.root.removeEventListener("mouseenter", this._handleMouseEnter);
95	    this._elements.root.removeEventListener("mouseleave", this._handleMouseLeave);
96	    this._resizeObserver?.disconnect();
97	    this._resizeObserver = null;
98	    this._killTween();
99	    this._elements.root.classList.remove(MARQUEE.fallbackClass);
100	    this._elements.track.style.transform = "";
101	    this._elements.root.style.removeProperty(MARQUEE.fallbackDurationVar);
102	    this._clones.forEach((clone) => {
103	      if (clone.parentElement === this._elements.track) {
104	        this._elements.track.removeChild(clone);
105	      }
106	    });
107	    this._clones = [];
108	  }
109	
110	  private _buildClones(): void {
111	    this._clones.forEach((clone) => {
112	      if (clone.parentElement === this._elements.track) {
113	        this._elements.track.removeChild(clone);
114	      }
115	    });
116	    this._clones = [];
117	
118	    const itemWidth = this._elements.item.offsetWidth;
119	    const viewportWidth = this._elements.viewport.offsetWidth;
120	    if (itemWidth <= 0 || viewportWidth <= 0) return;
121	
122	    const cloneCount = Math.max(1, Math.ceil(viewportWidth / itemWidth) + 1);
123	    for (let index = 0; index < cloneCount; index += 1) {
124	      const clone = this._elements.item.cloneNode(true) as HTMLElement;
125	      Aria.setHidden(clone, true);
126	      this._elements.track.appendChild(clone);
127	      this._clones.push(clone);
128	    }
129	  }
130	
131	  private _observeResize(): void {
132	    if (typeof ResizeObserver === "undefined") return;
133	    this._resizeObserver = new ResizeObserver(() => this.refresh());
134	    this._resizeObserver.observe(this._elements.viewport);
135	    this._resizeObserver.observe(this._elements.item);
136	  }
137	
138	  private _killTween(): void {
139	    this._tween?.kill?.();
140	    this._tween = null;
141	  }
142	}
