144	export class Marquee {
145	  private static _items: MarqueeItemRuntime[] = [];
146	
147	  static init(options: MarqueeInitOptions = {}): void {
148	    Marquee.dispose();
149	    const selector = options.selector ?? MARQUEE.selector;
150	    const root = options.root ?? document;
151	    const roots = Array.from(root.querySelectorAll<HTMLElement>(selector));
152	    if (roots.length === 0) return;
153	
154	    Marquee._items = roots.flatMap((root) => {
155	      const elements = resolveElements(root);
156	      if (!elements) return [];
157	      return [
158	        new MarqueeItemRuntime({
159	          elements,
160	          speed: toNumber(root.dataset.marqueeSpeed, MARQUEE.speed),
161	          pauseOnHover:
162	            root.dataset.marqueePauseOnHover !== "false" &&
163	            MARQUEE.pauseOnHover,
164	        }),
165	      ];
166	    });
167	
168	    Marquee._items.forEach((item) => item.init());
169	  }
170	
171	  static dispose(): void {
172	    Marquee._items.forEach((item) => item.dispose());
173	    Marquee._items = [];
174	  }
175	}
